    private val cache = HashMap<String, ImageVector>()

    /** Ścieżka SVG → ImageVector dla Compose (zapamiętywany). */
    fun vector(path: String): ImageVector = cache.getOrPut(path) {
        ImageVector.Builder(defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
            .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
            .build()
    }
}

/** Ikona z [PgmIcons]. */
@Composable
fun PgmIcon(path: String, contentDescription: String?, modifier: Modifier = Modifier, tint: Color = LocalContentColor.current) {
    Icon(PgmIcons.vector(path), contentDescription = contentDescription, modifier = modifier, tint = tint)
}
